const shallow = { root: 0, map: 16, e1: 100, e2: 100, shared: 999 };
const edges = {
  root: ['map', 'shared'],   // shared also reachable directly from root
  map: ['e1', 'e2', 'shared'],
  e1: [], e2: [], shared: [],
};

// reachable from root if we DELETE `map` (and its outgoing edges)
function reachableWithout(removed) {
  const seen = new Set();
  const q = ['root'];
  while (q.length) {
    const n = q.shift();
    if (n === removed || seen.has(n)) continue;
    seen.add(n);
    for (const m of edges[n]) if (m !== removed) q.push(m);
  }
  return seen;
}

const withMap = reachableWithout(null);
const withoutMap = reachableWithout('map');
// retained by map = shallow of nodes that drop out when map is removed
let retained = 0;
for (const n of withMap) {
  if (!withoutMap.has(n)) retained += shallow[n];
}
console.log('retained(map)=' + retained);

